    // --- client/tool-views.js ---
    function parseToolArgsSafe(block) {
      if (!block || typeof block !== 'object') return {}
      const direct = block.call?.args ?? block.args
      if (direct && typeof direct === 'object' && !Array.isArray(direct)) return direct
      const raw = block.call?.argsRaw ?? block.argsRaw ?? ''
      if (typeof raw === 'string' && raw.trim()) {
        try {
          const parsed = JSON.parse(raw)
          if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed
        } catch {}
      }
      return {}
    }

    function extractOutputText(block) {
      if (!block || typeof block !== 'object' || !Array.isArray(block.content)) return ''
      return block.content
        .filter((item) => item && item.type === 'text' && typeof item.text === 'string' && item.text.trim())
        .map((item) => item.text.trim())
        .join('\n')
    }

    function createMemoryToolView({ React, getLocale, subscribeLocale }) {
      const h = React.createElement

      return function MemoryToolView({ toolName, phase, block }) {
        const [langTick, setLangTick] = React.useState(0)
        const [expanded, setExpanded] = React.useState(false)

        React.useEffect(() => {
          if (typeof subscribeLocale !== 'function') return undefined
          return subscribeLocale(() => setLangTick((n) => n + 1))
        }, [])
        void langTick

        const t = createTranslator(typeof getLocale === 'function' ? getLocale() : 'en')
        const name = String(toolName || block?.call?.name || '').trim()
        const args = parseToolArgsSafe(block)
        const outputText = extractOutputText(block)
        const isError = Boolean(block?.isError)
        const isRunning = phase === 'call' || phase === 'running' || phase === 'pending'

        let titleKey = 'toolSaveTitle'
        let iconEl = h(MemoryNavIcon, { React, size: 14 })
        let preview = ''

        if (name === 'memory_save') {
          titleKey = 'toolSaveTitle'
          iconEl = h(SparkleIcon, { React, size: 14 })
          preview = args.title || args.summary || ''
        } else if (name === 'memory_update') {
          titleKey = 'toolUpdateTitle'
          iconEl = h(SparkleIcon, { React, size: 14 })
          preview = args.title || args.id || ''
        } else if (name === 'memory_delete') {
          titleKey = 'toolDeleteTitle'
          iconEl = h(TrashIcon, { React, size: 14 })
          preview = args.id || ''
        } else if (name === 'memory_search') {
          titleKey = 'toolSearchTitle'
          iconEl = h(SearchIcon, { React, size: 14 })
          preview = args.query ? `"${args.query}"` : (args.category || '')
        } else if (name === 'memory_get') {
          titleKey = 'toolGetTitle'
          iconEl = h(MemoryNavIcon, { React, size: 14 })
          preview = Array.isArray(args.ids) ? args.ids.join(', ') : (args.id || '')
        } else if (name === 'env_snapshot') {
          titleKey = 'toolEnvTitle'
          iconEl = h(ServerIcon, { React, size: 14 })
          preview = outputText.split('\n')[0] || ''
        }

        const statusText = isRunning ? t('toolRunning') : (isError ? t('toolFailed') : t('toolDone'))
        const categoryBadge = args.category
          ? h('span', { className: `smem-badge cat-${String(args.category).toLowerCase()}` }, String(args.category))
          : null

        return h(
          'div',
          { className: 'smem-tool-card' },
          h(
            'div',
            {
              className: 'smem-tool-head',
              role: 'button',
              tabIndex: 0,
              onClick: () => setExpanded((v) => !v),
              onKeyDown: (e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault()
                  setExpanded((v) => !v)
                }
              },
            },
            h(
              'div',
              { className: 'smem-tool-head-left' },
              iconEl,
              h('span', { className: 'smem-tool-title' }, t(titleKey)),
              categoryBadge,
              preview ? h('span', { className: 'smem-tool-preview' }, preview) : null,
            ),
            h(
              'div',
              { style: { display: 'inline-flex', alignItems: 'center', gap: '6px', flexShrink: 0 } },
              h('span', { className: `smem-badge${isError ? '' : ' src-agent'}` }, statusText),
              outputText ? h(ChevronIcon, { React, size: 13, expanded }) : null,
            ),
          ),
          expanded && outputText
            ? h('div', { className: 'smem-tool-body' }, outputText)
            : null,
        )
      }
    }

    // --- client/memory-controller.js ---
    const MEM_STATE_API = 'api/sandbox-memory.state'
    const MEM_CREATE_API = 'api/sandbox-memory.create'
    const MEM_UPDATE_API = 'api/sandbox-memory.update'
    const MEM_DELETE_API = 'api/sandbox-memory.delete'
    const MEM_CLEAR_API = 'api/sandbox-memory.clear'
    const MEM_SETTINGS_API = 'api/sandbox-memory.settings'
    const MEM_ENV_REFRESH_API = 'api/sandbox-memory.env-refresh'
    const MEM_EXPORT_API = 'api/sandbox-memory.export'
    const MEM_IMPORT_API = 'api/sandbox-memory.import'

    function defaultMemoryUiState() {
      return {
        memories: [],
        settings: { ...DEFAULT_SETTINGS, envSections: { ...DEFAULT_SETTINGS.envSections } },
        envSnapshot: {
          info: {},
          toolchains: [],
          projects: [],
          services: [],
          routes: [],
          cron: [],
          scannedAt: 0,
        },
        preview: {
          guideText: '',
          envText: '',
          indexText: '',
          contextText: '',
          budget: {
            guideTokens: 0,
            envTokens: 0,
            indexTokens: 0,
            totalTokens: 0,
            indexChars: 0,
            maxIndexChars: 2800,
            includedCount: 0,
            omittedCount: 0,
            totalEnabledCount: 0,
          },
        },
        stats: {
          total: 0,
          enabled: 0,
          disabled: 0,
          pinned: 0,
          byCategory: {},
          bySource: { auto: 0, agent: 0, manual: 0 },
        },
        storageDir: '',
        indexFile: '',
      }
    }

    function createMemoryController({
      fetchImpl = globalThis.fetch,
    } = {}) {
      let state = defaultMemoryUiState()
      let busy = false
      let syncing = false
      let lastRev = ''
      let toast = null
      let toastTimer = null
      let syncInFlight = null
      let disposed = false
      const listeners = new Set()

      function emit() {
        if (disposed) return
        for (const fn of listeners) {
          try { fn() } catch {}
        }
      }

      function showToast(kind, key, detail = '') {
        if (toastTimer) clearTimeout(toastTimer)
        toast = { kind, key, detail, id: Date.now() }
        emit()
        toastTimer = setTimeout(() => {
          toast = null
          toastTimer = null
          emit()
        }, 3600)
        toastTimer.unref?.()
      }

      function clearToast() {
        if (toastTimer) {
          clearTimeout(toastTimer)
          toastTimer = null
        }
        toast = null
        emit()
      }

      function applyState(nextState, rev = '') {
        if (nextState && typeof nextState === 'object') {
          state = {
            ...defaultMemoryUiState(),
            ...nextState,
          }
        }
        if (rev !== undefined && rev !== '') {
          lastRev = String(rev)
        }
      }

      async function requestJson(url, opts = {}) {
        if (typeof fetchImpl !== 'function') {
          return { ok: false, error: 'Fetch unavailable' }
        }
        try {
          const res = await fetchImpl(url, {
            credentials: 'same-origin',
            headers: {
              'content-type': 'application/json',
              ...(opts.headers || {}),
            },
            ...opts,
          })
          const data = await res.json().catch(() => ({}))
          if (!res.ok || data.ok === false) {
            return { ok: false, error: data.error || `HTTP ${res.status}` }
          }
          return data
        } catch (err) {
          return { ok: false, error: err?.message || String(err) }
        }
      }

      async function syncFromHost({ force = false } = {}) {
        if (disposed) return state
        if (syncInFlight && !force) return syncInFlight
        syncing = true
        const url = !force && lastRev ? `${MEM_STATE_API}?rev=${encodeURIComponent(lastRev)}` : MEM_STATE_API
        syncInFlight = (async () => {
          const data = await requestJson(url, { method: 'GET' })
          if (data.ok && !data.unchanged && data.state) {
            applyState(data.state, data.rev)
            emit()
          } else if (data.ok && data.rev) {
            lastRev = String(data.rev)
          }
          return state
        })().finally(() => {
          syncing = false
          syncInFlight = null
        })
        return syncInFlight
      }

      async function mutate(url, body, successKey) {
        busy = true
        emit()
        try {
          const data = await requestJson(url, {
            method: 'POST',
            body: JSON.stringify(body || {}),
          })
          if (!data.ok) {
            showToast('error', 'toastError', data.error || '')
            return data
          }
          if (data.state) {
            applyState(data.state, '')
            lastRev = ''
          }
          if (successKey) showToast('ok', successKey)
          else emit()
          return data
        } finally {
          busy = false
          emit()
        }
      }

      async function createMemory(payload) {
        return mutate(MEM_CREATE_API, payload, 'toastSaved')
      }

      async function updateMemory(id, patch) {
        return mutate(MEM_UPDATE_API, { id, ...patch }, 'toastUpdated')
      }

      async function deleteMemory(id) {
        return mutate(MEM_DELETE_API, { id }, 'toastDeleted')
      }

      async function clearAutoMemories() {
        return mutate(MEM_CLEAR_API, { source: 'auto' }, 'toastCleared')
      }

      async function saveSettings(patch) {
        return mutate(MEM_SETTINGS_API, { settings: patch }, 'toastSettingsSaved')
      }

      async function refreshEnvironment(forceToolchains = false) {
        return mutate(MEM_ENV_REFRESH_API, { forceToolchains }, 'toastEnvRefreshed')
      }

      async function exportMemories() {
        const data = await requestJson(MEM_EXPORT_API, { method: 'GET' })
        if (!data.ok) {
          showToast('error', 'toastError', data.error || '')
          return null
        }
        showToast('ok', 'toastExported')
        return data.data
      }

      async function importMemories(payload, mode = 'merge') {
        return mutate(MEM_IMPORT_API, { payload, mode }, 'toastImported')
      }

      function getSnapshot() {
        return {
          state,
          busy,
          syncing,
          toast,
        }
      }

      function subscribe(listener) {
        listeners.add(listener)
        return () => listeners.delete(listener)
      }

      function dispose() {
        disposed = true
        if (toastTimer) {
          clearTimeout(toastTimer)
          toastTimer = null
        }
        listeners.clear()
      }

      return {
        getSnapshot,
        subscribe,
        syncFromHost,
        createMemory,
        updateMemory,
        deleteMemory,
        clearAutoMemories,
        saveSettings,
        refreshEnvironment,
        exportMemories,
        importMemories,
        showToast,
        clearToast,
        dispose,
      }
    }

    // --- client/memory-page.js ---
    function categoryLabelKey(cat) {
      switch (cat) {
        case 'preference': return 'catPreference'
        case 'project': return 'catProject'
        case 'environment': return 'catEnvironment'
        case 'workflow': return 'catWorkflow'
        case 'pitfall': return 'catPitfall'
        default: return 'catFact'
      }
    }

    function sourceLabelKey(src) {
      if (src === 'auto') return 'srcAuto'
      if (src === 'agent') return 'srcAgent'
      return 'srcManual'
    }

    function formatMemoryTime(ts, lang) {
      if (!ts) return '—'
      const diffSec = Math.max(0, Math.floor((Date.now() - Number(ts)) / 1000))
      if (diffSec < 60) return lang === 'zh' ? '刚刚' : 'just now'
      if (diffSec < 3600) {
        const m = Math.floor(diffSec / 60)
        return lang === 'zh' ? `${m} 分钟前` : `${m}m ago`
      }
      if (diffSec < 86400) {
        const h = Math.floor(diffSec / 3600)
        return lang === 'zh' ? `${h} 小时前` : `${h}h ago`
      }
      const d = Math.floor(diffSec / 86400)
      if (d < 30) return lang === 'zh' ? `${d} 天前` : `${d}d ago`
      try {
        return new Date(Number(ts)).toISOString().slice(0, 10)
      } catch {
        return '—'
      }
    }

    function copyMemoryText(text) {
      const nav = typeof navigator !== 'undefined' ? navigator : null
      if (nav?.clipboard?.writeText) {
        return nav.clipboard.writeText(String(text || '')).then(() => true).catch(() => false)
      }
      return Promise.resolve(false)
    }

    function downloadJsonFile(data, filename) {
      if (typeof document === 'undefined' || typeof Blob === 'undefined' || typeof URL === 'undefined') return false
      try {
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json;charset=utf-8' })
        const url = URL.createObjectURL(blob)
        const a = document.createElement('a')
        a.href = url
        a.download = filename
        document.body.appendChild(a)
        a.click()
        a.remove()
        setTimeout(() => URL.revokeObjectURL(url), 1000)
        return true
      } catch {
        return false
      }
    }

