          setFormSummary(entry.summary || '')
          setFormContent(entry.content || '')
          setFormTags(Array.isArray(entry.tags) ? entry.tags.join(', ') : '')
          setFormPinned(Boolean(entry.pinned))
          setFormEnabled(entry.enabled !== false)
